-- =====================================================================
-- Loan Portal — lender policies (from "Policy details as per 2024.xlsx")
-- Run AFTER schema.sql, in Supabase → SQL Editor. Safe to run again: it replaces the lender rows.
--
-- One row per lender policy column in the sheet (26 with data). Contact persons and phone
-- numbers from the sheet are NOT stored. Numbers such as minimum salary / CIBIL / age were read
-- from the sheet's text; the full original text of every row is kept in "policy" and is also
-- given to the Gemini assistant. Edit any value later in Table Editor → lenders.
-- The sheet describes PERSONAL LOAN policies. For other loan types results are marked "check with bank".
-- =====================================================================

create table if not exists public.lenders (
  id                    text primary key,
  bank_name             text not null,
  variant               text not null default '',      -- "Policy 2" when the sheet has several columns for one bank
  product               text not null default 'Personal Loan',
  min_salary_listed     integer,     -- ₹ per month, listed companies
  min_salary_unlisted   integer,     -- ₹ per month, non-listed companies
  min_cibil             integer,
  min_age               integer,
  max_age               integer,
  min_exp_months        integer,
  min_loan_amount       bigint,
  max_loan_amount       bigint,
  max_tenure_months     integer,
  max_foir_pct          numeric,     -- all EMIs as % of income
  roi_min               numeric,     -- % per year
  roi_max               numeric,
  unlisted_allowed      boolean,     -- null = not stated / depends on profile
  contract_emp_allowed  boolean,
  bpo_nbfc_allowed      boolean,     -- BPO, pharma, NBFC, insurance, real estate employers
  active                boolean not null default true,
  policy                jsonb not null default '{}'::jsonb,   -- "row. criterion" → original sheet text
  updated_at            timestamptz not null default now()
);
alter table public.lenders enable row level security;
drop policy if exists lenders_read on public.lenders;
create policy lenders_read on public.lenders for select to authenticated using (true);
revoke all on public.lenders from anon, authenticated;
grant select on public.lenders to authenticated;       -- read-only for signed-in users; edit in the Supabase dashboard

