on conflict (id) do update set bank_name = excluded.bank_name, variant = excluded.variant, product = excluded.product, min_salary_listed = excluded.min_salary_listed, min_salary_unlisted = excluded.min_salary_unlisted, min_cibil = excluded.min_cibil, min_age = excluded.min_age, max_age = excluded.max_age, min_exp_months = excluded.min_exp_months, min_loan_amount = excluded.min_loan_amount, max_loan_amount = excluded.max_loan_amount, max_tenure_months = excluded.max_tenure_months, max_foir_pct = excluded.max_foir_pct, roi_min = excluded.roi_min, roi_max = excluded.roi_max, unlisted_allowed = excluded.unlisted_allowed, contract_emp_allowed = excluded.contract_emp_allowed, bpo_nbfc_allowed = excluded.bpo_nbfc_allowed, policy = excluded.policy, updated_at = now();

-- ---------------------------------------------------------------------
-- check_lenders(application id): compare one application with every lender.
-- Runs as the signed-in person (RLS applies), so it only works on their own applications.
--   result  'eligible'      can apply: meets every written rule
--           'check'         may apply: nothing breaks a rule, but something needs confirming
--           'not_eligible'  can't apply: breaks at least one written rule
-- Never a guarantee — the lender makes the final decision.
-- ---------------------------------------------------------------------
create or replace function public.check_lenders(p_application uuid)
returns table (
  lender_id text, bank_name text, variant text, result text, score integer,
  reasons_ok text[], reasons_check text[], reasons_fail text[],
  roi_min numeric, roi_max numeric, max_loan bigint, eligible_amount bigint, est_emi integer, max_foir numeric
)
language plpgsql stable security invoker set search_path = public as $$
declare
  a record;
  d jsonb; v_income numeric; v_emi numeric; v_cibil integer; v_age integer; v_exp integer; v_amount numeric; v_months integer;
  v_comp text; v_pay text; v_ind text; v_loan text; v_enq integer; v_bounce integer; v_settled text;
begin
  select * into a from public.applications where id = p_application;     -- RLS: only your own
  if not found then raise exception 'Application not found.' using errcode = 'P0002'; end if;
  d := a.data;
  v_income := nullif(regexp_replace(coalesce(d->'work'->>'income',''), '[^0-9.]', '', 'g'), '')::numeric
            + coalesce(nullif(regexp_replace(coalesce(d->'work'->>'otherIncome',''), '[^0-9.]', '', 'g'), '')::numeric, 0);
  v_emi    := coalesce(nullif(regexp_replace(coalesce(d->'loan'->>'existingEmi',''), '[^0-9.]', '', 'g'), '')::numeric, 0);
  v_cibil  := nullif(regexp_replace(coalesce(d->'loan'->>'cibil',''), '[^0-9]', '', 'g'), '')::integer;
  v_age    := case when coalesce(d->'personal'->>'dob','') ~ '^\d{4}-\d{2}-\d{2}$' then extract(year from age((d->'personal'->>'dob')::date))::integer end;
  v_exp    := round(coalesce(nullif(regexp_replace(coalesce(d->'work'->>'experience',''), '[^0-9.]', '', 'g'), '')::numeric, 0) * 12)::integer;
  v_amount := nullif(regexp_replace(coalesce(d->'loan'->>'amount',''), '[^0-9.]', '', 'g'), '')::numeric;
  v_months := round(coalesce(nullif(regexp_replace(coalesce(d->'loan'->>'tenure',''), '[^0-9.]', '', 'g'), '')::numeric, 5) * 12)::integer;
  v_comp   := lower(coalesce(d->'work'->>'companyType', ''));        -- listed | unlisted | government | proprietorship | partnership
  v_pay    := lower(coalesce(d->'work'->>'payroll', ''));            -- permanent | contract | third_party | self_employed
  v_ind    := lower(coalesce(d->'work'->>'industry', ''));
  v_loan   := coalesce(d->'loan'->>'loanType', '');
  v_enq    := nullif(regexp_replace(coalesce(d->'loan'->>'enquiries',''), '[^0-9]', '', 'g'), '')::integer;
  v_bounce := nullif(regexp_replace(coalesce(d->'loan'->>'bounces',''), '[^0-9]', '', 'g'), '')::integer;
  v_settled:= lower(coalesce(d->'loan'->>'settled', ''));

  return query
  with base as (
    select l.*,
      least(coalesce(l.max_tenure_months, v_months), v_months) as months,
      coalesce(l.roi_min, 12)::numeric as rate,
      case when v_comp in ('unlisted','proprietorship','partnership') then coalesce(l.min_salary_unlisted, l.min_salary_listed) else l.min_salary_listed end as min_sal
    from public.lenders l where l.active
  ), calc as (
    select b.*,
      case when b.rate > 0 and b.months > 0 then (b.rate / 1200) * power(1 + b.rate / 1200, b.months) / (power(1 + b.rate / 1200, b.months) - 1) end as emi_factor
    from base b
  ), rules as (
    select c.*,
      case when c.emi_factor is not null and v_income is not null
           then greatest(0, (v_income * coalesce(c.max_foir_pct, 60) / 100 - v_emi) / c.emi_factor) end as foir_cap,
      array_remove(array[
        case when v_cibil is not null and c.min_cibil is not null and v_cibil < c.min_cibil then format('CIBIL %s is below the minimum of %s', v_cibil, c.min_cibil) end,
        case when v_income is not null and c.min_sal is not null and v_income < c.min_sal then format('Income ₹%s is below the minimum of ₹%s a month', to_char(v_income, 'FM99,99,99,999'), to_char(c.min_sal, 'FM99,99,99,999')) end,
        case when v_age is not null and c.min_age is not null and v_age < c.min_age then format('Age %s is below the minimum of %s', v_age, c.min_age) end,
        case when v_age is not null and c.max_age is not null and v_age > c.max_age then format('Age %s is above the maximum of %s', v_age, c.max_age) end,
        case when c.min_exp_months is not null and v_exp < c.min_exp_months then format('Work experience of %s months is below the minimum of %s months', v_exp, c.min_exp_months) end,
        case when v_amount is not null and c.min_loan_amount is not null and v_amount < c.min_loan_amount then format('Lends from ₹%s upwards', to_char(c.min_loan_amount, 'FM99,99,99,999')) end,
        case when v_comp in ('unlisted','proprietorship','partnership') and c.unlisted_allowed is false then 'Does not lend to employees of non-listed companies' end,
        case when v_pay in ('contract','third_party') and c.contract_emp_allowed is false then 'Does not lend to contract / third-party payroll employees' end,
        case when c.bpo_nbfc_allowed is false and v_ind in ('bpo','pharma','nbfc','insurance','real_estate') then 'Does not lend to employees in this industry' end,
        case when v_settled = 'open' then 'A settled loan is still showing on the credit report' end
      ]::text[], null) as fail
    from calc c
  ), scored as (
    select r.*,
      array_remove(array[
        case when v_cibil is not null and r.min_cibil is not null and v_cibil >= r.min_cibil then format('CIBIL %s meets the minimum of %s', v_cibil, r.min_cibil) end,
        case when v_income is not null and r.min_sal is not null and v_income >= r.min_sal then format('Income meets the minimum of ₹%s a month', to_char(r.min_sal, 'FM99,99,99,999')) end,
        case when v_age is not null and (r.min_age is not null or r.max_age is not null) and v_age between coalesce(r.min_age, 0) and coalesce(r.max_age, 200) then format('Age %s is within their limit', v_age) end,
        case when r.min_exp_months is not null and v_exp >= r.min_exp_months then 'Work experience is enough' end,
        case when r.foir_cap is not null and v_amount is not null and r.foir_cap >= v_amount then 'Income supports the EMI for the full amount' end
      ]::text[], null) as ok,
      array_remove(array[
        case when v_loan <> '' and v_loan <> r.product then format('Sheet has %s rules only; confirm their %s policy', lower(r.product), v_loan) end,
        case when v_cibil is null then 'CIBIL score not given' end,
        case when v_comp = '' then 'Employer type (listed / non-listed) not given' end,
        case when v_comp in ('unlisted','proprietorship','partnership') and r.unlisted_allowed is null then 'Non-listed companies: depends on the company category' end,
        case when v_pay = '' then 'Payroll type not given' end,
        case when v_pay in ('contract','third_party') and r.contract_emp_allowed is null then 'Contract employees: not stated in the sheet' end,
        case when r.min_cibil is null then 'Minimum CIBIL not stated in the sheet' end,
        case when v_amount is not null and r.max_loan_amount is not null and v_amount > r.max_loan_amount then format('Maximum loan is ₹%s', to_char(r.max_loan_amount, 'FM99,99,99,999')) end,
        case when r.foir_cap is not null and v_amount is not null and r.foir_cap < v_amount then format('Income supports about ₹%s at %s%% interest', to_char(round(r.foir_cap, -3), 'FM99,99,99,999'), r.rate) end,
        case when v_enq is not null and v_enq > 4 then format('%s credit enquiries in 3 months is high', v_enq) end,
        case when v_bounce is not null and v_bounce > 0 then format('%s EMI bounce(s) in 12 months', v_bounce) end,
        case when v_settled = 'cleared' then 'A settled loan in the past: lender will ask for the closure letter' end,
        case when v_months > coalesce(r.max_tenure_months, v_months) then format('Tenure limited to %s months', r.max_tenure_months) end
      ]::text[], null) as chk
    from rules r
  )
  select s.id, s.bank_name, s.variant,
    case when cardinality(s.fail) > 0 then 'not_eligible'
         when cardinality(s.chk) > 0 then 'check' else 'eligible' end,
    (case when cardinality(s.fail) > 0 then greatest(5, 40 - 10 * cardinality(s.fail))
          else greatest(50, 100 - 7 * cardinality(s.chk)) end)::integer,
    s.ok, s.chk, s.fail, s.roi_min, s.roi_max, s.max_loan_amount,
    case when v_amount is null then null else round(least(v_amount, coalesce(s.max_loan_amount, v_amount), coalesce(s.foir_cap, v_amount)), -3)::bigint end,
    case when s.emi_factor is null or v_amount is null then null
         else round(least(v_amount, coalesce(s.max_loan_amount, v_amount), coalesce(s.foir_cap, v_amount)) * s.emi_factor)::integer end,
    s.max_foir_pct
  from scored s
  order by case when cardinality(s.fail) > 0 then 3 when cardinality(s.chk) > 0 then 2 else 1 end,
           (case when cardinality(s.fail) > 0 then 0 else 100 - 7 * cardinality(s.chk) end) desc, s.roi_min nulls last, s.bank_name, s.variant;
end $$;
revoke execute on function public.check_lenders(uuid) from public, anon;
grant execute on function public.check_lenders(uuid) to authenticated;

-- Saved Gemini analysis for an application (written by the website after the assistant answers).
alter table public.applications add column if not exists ai_analysis jsonb;
